commitments:
{"language":"FCL-1","records":[
  {"id":"a1","type":"claim","text":"Both ambiguity in chore specifications and disagreement about the nature of the flat are plausible contributors to the conflict.","depends":["c1","r2"]},
  {"id":"a2","type":"commitment","text":"Run a short‑term specification pilot on two concrete chores, using a shared draft note that lists what counts as done, by when, and fallback if unable.","depends":["c2","u1"],"action":"Create the note, share it, and observe recurrence over the next two weeks","consequence":"If recurrence drops, supports the ambiguity reading; if not, suggests other factors dominate"},
  {"id":"a3","type":"commitment","text":"Hold brief, separate conversations with each flatmate to ask how they conceptualize the flat – as a shared unit with obligations or as three independent lives.","depends":["r2","r6"],"action":"Ask the question in a low‑pressure way, without framing it as a negotiation","consequence":"Provides data to discriminate between the two readings"},
  {"id":"a4","type":"commitment","text":"Observe the avoiding flatmate's response to the specification draft: whether they engage with its content or withdraw from the idea of a written arrangement.","depends":["r7"],"action":"Note whether they comment on the chores themselves or on the fact that a rule is being codified","bearing":"Helps decide which hypothesis is more accurate"},
  {"id":"a5","type":"commitment","text":"If the specification pilot and household‑concept probe do not reduce friction, trial a "truce" arrangement such as fixed personal zones or a rotation with a default outcome.","depends":["r8"],"action":"Implement the truce for a trial week","consequence":"Reduces negotiation needs and tests whether low‑binding structures are acceptable"},
  {"id":"a6","type":"commitment","text":"Should the truce also fail, explicitly raise the question of whether the current living arrangement fits the participants' needs.","depends":["r11"],"action":"Facilitate a group discussion about lease and cohabitation suitability","consequence":"Allows a broader decision rather than endless chore disputes"},
  {"id":"a7","type":"objection","text":"Both the original objection (o1) and the rival objection (r9) warn that focusing on specifications or truce rules may miss relational fatigue or appear coercive.","bearing":"Reminds all steps to stay voluntary, informal, and subject to review"}
],"uptake":["a1","a2","a3","a4","a5","a6","a7"]}
